      agent-skills,
      agent-artifacts,
      anthropic-skills,
      cloudflare-skills,
      mattpocock-skills,
      mholtzscher-skills,
      plannotator-skills,
      vercel-agent-browser,
      nicobailon-visual-explainer,
      today,
      helium,
      hunk,
      sem,
      herdr,
      zellmin,
      ...
